import{_ as t,a0 as p,w as o,s as r,ao as c,I as a,x as n,a1 as e,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何在 Linux 服務器上設置 ulimit 和文件描述符數限制 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 服務器上設置 ulimit 和文件描述符數限制 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 服務器上設置 ulimit 和文件描述符數限制 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 服務器上設置 ulimit 和文件描述符數限制 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190609 How to set ulimit and file descriptors limit on Linux Servers","title":"如何在 Linux 服務器上設置 ulimit 和文件描述符數限制","tag":"201907","desc":""},"relativePath":"201907/20190609 How to set ulimit and file descriptors limit on Linux Servers.md","filePath":"[post].md"}'),d={name:"201907/20190609 How to set ulimit and file descriptors limit on Linux Servers.md"};function u(h,s,m,g,b,k){const i=p("Link");return o(),r("div",null,[s[18]||(s[18]=c(`<h1 id="如何在-linux-服務器上設置-ulimit-和文件描述符數限制" tabindex="-1">如何在 Linux 服務器上設置 ulimit 和文件描述符數限制 <a class="header-anchor" href="#如何在-linux-服務器上設置-ulimit-和文件描述符數限制" aria-label="Permalink to “如何在 Linux 服務器上設置 ulimit 和文件描述符數限制”">​</a></h1><p><strong>簡介</strong>：在生產環境中遇到打開文件數這類的挑戰如今已是司空見慣的事情了。因為許多應用程序是基於 Java 和 Apache 的，安裝和配置它們可能會導致打開過多的文件（文件描述符）。如果打開的文件描述符超過了默認設置的限制，就可能會面臨訪問控制問題，受阻於打開文件的挑戰。許多生產環境因此而陷入停滯狀態。</p><p><img src="https://img.linux.net.cn/data/attachment/album/201907/09/121422bv6t76nztjxqoprn.jpg" alt=""></p><p>幸運的是，在基於 Linux 的服務器上，都有 <code>ulimit</code> 命令，通過它可以查看、設置、獲取文件打開的狀態和配置詳情。此命令配備了許多選項，通過這些組合可以設置打開文件的數量。下面逐個命令用示例做了詳細説明。</p><h3 id="查看任何-linux-系統中當前打開文件數的限制" tabindex="-1">查看任何 Linux 系統中當前打開文件數的限制 <a class="header-anchor" href="#查看任何-linux-系統中當前打開文件數的限制" aria-label="Permalink to “查看任何 Linux 系統中當前打開文件數的限制”">​</a></h3><p>要在 Linux 服務器上得到打開文件數的限制，請執行以下命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@ubuntu ~]# cat /proc/sys/fs/file-max</span></span>
<span class="line"><span>146013</span></span></code></pre></div><p>上面的數字表明用户可以在每個用户登錄會話中打開 ‘146013’ 個文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@centos ~]# cat /proc/sys/fs/file-max</span></span>
<span class="line"><span>149219</span></span>
<span class="line"><span>[root@debian ~]# cat /proc/sys/fs/file-max</span></span>
<span class="line"><span>73906</span></span></code></pre></div><p>這清楚地表明，各個 Linux 操作系統具有不同的打開文件數限制。這基於各自系統中運行的依賴關係和應用程序。</p><h3 id="ulimit-命令" tabindex="-1">ulimit 命令 <a class="header-anchor" href="#ulimit-命令" aria-label="Permalink to “ulimit 命令”">​</a></h3><p>顧名思義，<code>ulimit</code>（用户限制）用於顯示和設置登錄用户的資源限制。當我們使用 <code>-a</code> 選項運行 <code>ulimit</code> 命令時，它將打印登錄用户的所有資源限制。現在讓我們在 Ubuntu/Debian 和 CentOS 系統上運行 <code>ulimit -a</code>，</p><h4 id="ubuntu-debian-系統" tabindex="-1">Ubuntu / Debian 系統 <a class="header-anchor" href="#ubuntu-debian-系統" aria-label="Permalink to “Ubuntu / Debian 系統”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shashi@Ubuntu ~}$ ulimit -a</span></span>
<span class="line"><span>core file size          (blocks, -c) 0</span></span>
<span class="line"><span>data seg size           (kbytes, -d) unlimited</span></span>
<span class="line"><span>scheduling priority             (-e) 0</span></span>
<span class="line"><span>file size               (blocks, -f) unlimited</span></span>
<span class="line"><span>pending signals                 (-i) 5731</span></span>
<span class="line"><span>max locked memory       (kbytes, -l) 64</span></span>
<span class="line"><span>max memory size         (kbytes, -m) unlimited</span></span>
<span class="line"><span>open files                      (-n) 1024      </span></span>
<span class="line"><span>pipe size            (512 bytes, -p) 8</span></span>
<span class="line"><span>POSIX message queues     (bytes, -q) 819200</span></span>
<span class="line"><span>real-time priority              (-r) 0</span></span>
<span class="line"><span>stack size              (kbytes, -s) 8192</span></span>
<span class="line"><span>cpu time               (seconds, -t) unlimited</span></span>
<span class="line"><span>max user processes              (-u) 5731</span></span>
<span class="line"><span>virtual memory          (kbytes, -v) unlimited</span></span>
<span class="line"><span>file locks                      (-x) unlimited</span></span></code></pre></div><h4 id="centos-系統" tabindex="-1">CentOS 系統 <a class="header-anchor" href="#centos-系統" aria-label="Permalink to “CentOS 系統”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shashi@centos ~}$ ulimit -a</span></span>
<span class="line"><span>core file size          (blocks, -c) 0</span></span>
<span class="line"><span>data seg size           (kbytes, -d) unlimited</span></span>
<span class="line"><span>scheduling priority             (-e) 0</span></span>
<span class="line"><span>file size               (blocks, -f) unlimited</span></span>
<span class="line"><span>pending signals                 (-i) 5901</span></span>
<span class="line"><span>max locked memory       (kbytes, -l) 64</span></span>
<span class="line"><span>max memory size         (kbytes, -m) unlimited</span></span>
<span class="line"><span>open files                      (-n) 1024</span></span>
<span class="line"><span>pipe size            (512 bytes, -p) 8</span></span>
<span class="line"><span>POSIX message queues     (bytes, -q) 819200</span></span>
<span class="line"><span>real-time priority              (-r) 0</span></span>
<span class="line"><span>stack size              (kbytes, -s) 8192</span></span>
<span class="line"><span>cpu time               (seconds, -t) unlimited</span></span>
<span class="line"><span>max user processes              (-u) 5901</span></span>
<span class="line"><span>virtual memory          (kbytes, -v) unlimited</span></span>
<span class="line"><span>file locks                      (-x) unlimited</span></span></code></pre></div><p>正如我們可以在這裏看到的，不同的操作系統具有不同的限制設置。所有這些限制都可以使用 <code>ulimit</code> 命令進行配置/更改。</p><p>要顯示單個資源限制，可以在 <code>ulimit</code> 命令中傳遞特定的參數，下面列出了一些參數：</p><ul><li><code>ulimit -n</code> –&gt; 顯示打開文件數限制</li><li><code>ulimit -c</code> –&gt; 顯示核心轉儲文件大小</li><li><code>umilit -u</code> –&gt; 顯示登錄用户的最大用户進程數限制</li><li><code>ulimit -f</code> –&gt; 顯示用户可以擁有的最大文件大小</li><li><code>umilit -m</code> –&gt; 顯示登錄用户的最大內存大小</li><li><code>ulimit -v</code> –&gt; 顯示最大內存大小限制</li></ul><p>使用以下命令檢查登錄用户打開文件數量的硬限制和軟限制：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shashi@Ubuntu ~}$ ulimit -Hn</span></span>
<span class="line"><span>1048576</span></span>
<span class="line"><span>shashi@Ubuntu ~}$ ulimit -Sn</span></span>
<span class="line"><span>1024</span></span></code></pre></div><h3 id="如何修復達到最大文件數限制的問題" tabindex="-1">如何修復達到最大文件數限制的問題？ <a class="header-anchor" href="#如何修復達到最大文件數限制的問題" aria-label="Permalink to “如何修復達到最大文件數限制的問題？”">​</a></h3><p>讓我們假設我們的 Linux 服務器已經達到了打開文件的最大數量限制，並希望在系統範圍擴展該限制，例如，我們希望將 100000 設置為打開文件數量的限制。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@ubuntu~]# sysctl -w fs.file-max=100000</span></span>
<span class="line"><span>fs.file-max = 100000</span></span></code></pre></div><p>上述更改將在下次重啓之前有效，因此要使這些更改在重啓後仍存在，請編輯文件 <code>/etc/sysctl.conf</code> 並添加相同的參數，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@ubuntu~]# vi /etc/sysctl.conf</span></span>
<span class="line"><span>fs.file-max = 100000</span></span></code></pre></div><p>保存文件並退出。</p><p>運行下面命令，使上述更改立即生效，而無需註銷和重新啓動。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@ubuntu~]# sysctl -p</span></span></code></pre></div><p>現在驗證新的更改是否生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@ubuntu~]# cat /proc/sys/fs/file-max</span></span>
<span class="line"><span>100000</span></span></code></pre></div><p>使用以下命令找出當前正在使用的文件描述符數量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@ansible ~]# more /proc/sys/fs/file-nr</span></span>
<span class="line"><span>1216    0       100000</span></span></code></pre></div><p>注意：命令 <code>sysctl -p</code> 用於在不重新啓動和註銷的情況下提交更改。</p><h3 id="通過-limit-conf-文件設置用户級資源限制" tabindex="-1">通過 limit.conf 文件設置用户級資源限制 <a class="header-anchor" href="#通過-limit-conf-文件設置用户級資源限制" aria-label="Permalink to “通過 limit.conf 文件設置用户級資源限制”">​</a></h3><p><code>/etc/sysctl.conf</code> 文件用於設置系統範圍的資源限制，但如果要為 Oracle、MariaDB 和 Apache 等特定用户設置資源限制，則可以通過 <code>/etc/security/limits.conf</code> 文件去實現。</p><p>示例 <code>limits.conf</code> 如下所示，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@ubuntu~]# cat /etc/security/limits.conf</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/Limits-conf-linux-part1-1024x677.jpg" alt="Limits-conf-linux-part1"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/06/Limits-conf-linux-part2-1024x443.jpg" alt="Limits-conf-linux-part2"></p><p>假設我們要為 linuxtechi 用户設置打開文件數量的硬限制和軟限制，而對於 oracle 用户設置打開進程數量的硬限制和軟限制，編輯文件 <code>/etc/security/limits.conf</code> 並添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># hard limit for max opened files for linuxtechi user</span></span>
<span class="line"><span>linuxtechi       hard    nofile          4096</span></span>
<span class="line"><span># soft limit for max opened files for linuxtechi user</span></span>
<span class="line"><span>linuxtechi       soft    nofile          1024</span></span>
<span class="line"><span></span></span>
<span class="line"><span># hard limit for max number of process for oracle user</span></span>
<span class="line"><span>oracle           hard    nproc          8096</span></span>
<span class="line"><span># soft limit for max number of process for oracle user</span></span>
<span class="line"><span>oracle           soft    nproc          4096</span></span></code></pre></div><p>保存文件並退出。</p><p><strong>注意：</strong> 如果你想對一個組而不是用户進行資源限制，那麼也可以通過 <code>limits.conf</code> 文件，輸入 <code>@&lt;組名&gt;</code> 代替用户名，其餘項都是相同的，示例如下，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># hard limit for max opened files for sysadmin group</span></span>
<span class="line"><span>@sysadmin        hard         nofile            4096 </span></span>
<span class="line"><span># soft limit for max opened files for sysadmin group</span></span>
<span class="line"><span>@sysadmin        soft         nofile            1024</span></span></code></pre></div><p>驗證新的更改是否生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~]# su - linuxtechi</span></span>
<span class="line"><span>~]$ ulimit -n -H</span></span>
<span class="line"><span>4096</span></span>
<span class="line"><span>~]$ ulimit -n -S</span></span>
<span class="line"><span>1024</span></span>
<span class="line"><span></span></span>
<span class="line"><span>~]# su - oracle</span></span>
<span class="line"><span>~]$ ulimit -H -u</span></span>
<span class="line"><span>8096</span></span>
<span class="line"><span>~]$ ulimit -S -u</span></span>
<span class="line"><span>4096</span></span></code></pre></div>`,47)),a("p",null,[s[1]||(s[1]=n("注：其他主要使用的命令是 ",-1)),e(i,{href:"https://www.linuxtechi.com/lsof-command-examples-linux-geeks/"},{default:l(()=>[...s[0]||(s[0]=[n("lsof",-1)])]),_:1}),s[2]||(s[2]=n("，可用於找出“當前打開了多少個文件”，這命令對管理員非常有幫助。",-1))]),s[19]||(s[19]=a("h3",{id:"結尾",tabindex:"-1"},[n("結尾 "),a("a",{class:"header-anchor",href:"#結尾","aria-label":"Permalink to “結尾”"},"​")],-1)),s[20]||(s[20]=a("p",null,[n("正如在介紹部分提到的，"),a("code",null,"ulimit"),n(" 命令非常強大，可以幫助用户配置並確保應用程序安裝更加流暢而沒有任何瓶頸。此命令有助於修復基於 Linux 的服務器中的（打開）大量文件的限制。")],-1)),s[21]||(s[21]=a("hr",null,null,-1)),a("p",null,[s[4]||(s[4]=n("via: ",-1)),e(i,{href:"https://www.linuxtechi.com/set-ulimit-file-descriptors-limit-linux-servers/"},{default:l(()=>[...s[3]||(s[3]=[n("https://www.linuxtechi.com/set-ulimit-file-descriptors-limit-linux-servers/",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=n("作者：",-1)),e(i,{href:"https://www.linuxtechi.com/author/shashidhar/"},{default:l(()=>[...s[5]||(s[5]=[n("Shashidhar Soppin",-1)])]),_:1}),s[10]||(s[10]=n(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[6]||(s[6]=[n("lujun9972",-1)])]),_:1}),s[11]||(s[11]=n(" 譯者：",-1)),e(i,{href:"https://github.com/zgj1024"},{default:l(()=>[...s[7]||(s[7]=[n("zgj1024",-1)])]),_:1}),s[12]||(s[12]=n(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[8]||(s[8]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[13]||(s[13]=[n("LCTT",-1)])]),_:1}),s[16]||(s[16]=n(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:l(()=>[...s[14]||(s[14]=[n("Linux中國",-1)])]),_:1}),s[17]||(s[17]=n(" 榮譽推出",-1))])])}const C=t(d,[["render",u]]);export{y as __pageData,C as default};
